const fs=require('fs');const crypto=require('crypto');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const results=[];
for (const mode of ['sync-functional','await-replacement','await-functional']) {
 const page=await browser.newPage();await page.setContent('<div id="root"></div>');
 await page.addScriptTag({path:'/tmp/edbot-cs35l-react-reference/react.js'});await page.addScriptTag({path:'/tmp/edbot-cs35l-react-reference/react-dom.js'});
 await page.evaluate(mode=>{window.trace=[];function App(){const [count,setCount]=React.useState(0);React.useLayoutEffect(()=>{window.trace.push({event:'commit',count})});
 async function click(){window.trace.push({event:'before',captured:count,dom:document.querySelector('button').textContent});
 if(mode==='sync-functional'){setCount(c=>c+1);setCount(c=>c+1);}else{const returned=mode==='await-functional'?setCount(c=>c+1):setCount(count+1);window.trace.push({event:'setter_return',type:typeof returned});await returned;window.trace.push({event:'after_await',captured:count,dom:document.querySelector('button').textContent});if(mode==='await-functional')setCount(c=>c+1);else setCount(count+1);}
 window.done=true;}
 return React.createElement('button',{onClick:click},String(count));}
 ReactDOM.createRoot(document.getElementById('root')).render(React.createElement(App));},mode);
 await page.locator('button').click();await page.waitForFunction(()=>window.done);await page.waitForTimeout(100);results.push({mode,react:await page.evaluate(()=>React.version),trace:await page.evaluate(()=>window.trace),final:await page.locator('button').textContent()});await page.close();}
 await browser.close();const sources={};for(const name of ['react.js','react-dom.js','check.cjs']){const data=fs.readFileSync('/tmp/edbot-cs35l-react-reference/'+name);sources[name]=crypto.createHash('sha256').update(data).digest('hex');}
 const report={checked_at:new Date().toISOString(),scope:'Isolated Chrome reference test, React 18.3.1 createRoot; not an EdBot or learner learning test.',bundle_urls:['https://unpkg.com/react@18.3.1/umd/react.development.js','https://unpkg.com/react-dom@18.3.1/umd/react-dom.development.js'],sources,runner_source:fs.readFileSync(__filename,'utf8'),results};fs.writeFileSync('/Users/tobiasduerschmid/Projects/edbot/output/profiling/cs35l-react-reference-v1.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(results,null,2));})().catch(e=>{console.error(e);process.exit(1)});
